<?php $pageTitle='Koreksi Identitas'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Petugas Rekam Medis','Administrator SIMRS']);$p=null;$msg='';$error='';$q='';if(isset($_POST['find'])){$q=trim($_POST['q']??'');$s=$pdo->prepare("SELECT * FROM patients WHERE medical_record_no=? OR nik=? OR LOWER(name) LIKE LOWER(?) LIMIT 1");$s->execute([$q,$q,'%'.$q.'%']);$p=$s->fetch();}if(isset($_POST['save'])){try{$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT * FROM patients WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p)throw new RuntimeException('Pasien tidak ditemukan.');$pdo->prepare("UPDATE patients SET name=?,phone=?,address=?,blood_type=?,marital_status=?,emergency_contact=? WHERE id=?")->execute([trim($_POST['name']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['blood_type']),trim($_POST['marital_status']),trim($_POST['emergency_contact']),$id]);audit($pdo,'CORRECT_IDENTITY','patients',$id,'Perubahan data administratif pasien '.$p['medical_record_no']);$msg='Perubahan data identitas berhasil disimpan.';$s->execute([$id]);$p=$s->fetch();}catch(Throwable $e){$error=$e->getMessage();}}include 'partials/header.php'; ?>
<?php if($msg): ?><div class="alert">✓ <?=e($msg)?></div><?php endif; ?><?php if($error): ?><div class="alert error">⚠ <?=e($error)?></div><?php endif; ?><div class="card"><div class="card-title"><div><h2>Pencarian data pasien</h2><p>Pilih pasien terlebih dahulu sebelum melakukan koreksi data administratif.</p></div></div><form method="post" class="search"><input name="q" value="<?=e($q)?>" placeholder="No. RM / NIK / nama pasien" required><button class="btn" name="find">Cari</button></form></div>
<?php if($p): ?><div class="card mt"><div class="card-title"><div><h2>Koreksi identitas</h2><p><?=e($p['medical_record_no'])?> • <?=e($p['name'])?></p></div><span class="badge blue">Identitas ditemukan</span></div><form method="post"><input type="hidden" name="id" value="<?=$p['id']?>"><div class="form-grid"><div><label>No. Rekam Medis</label><input value="<?=e($p['medical_record_no'])?>" readonly></div><div><label>NIK</label><input value="<?=e($p['nik'])?>" readonly></div><div><label>Nama Lengkap</label><input name="name" value="<?=e($p['name'])?>" required></div><div><label>No. Telepon</label><input name="phone" value="<?=e($p['phone'])?>"></div><div><label>Golongan Darah</label><select name="blood_type"><option value="">Belum diketahui</option><?php foreach(['A','B','AB','O'] as $b): ?><option <?=$b===$p['blood_type']?'selected':''?>><?=$b?></option><?php endforeach; ?></select></div><div><label>Status Pernikahan</label><select name="marital_status"><option value="">Pilih</option><?php foreach(['Belum Menikah','Menikah','Cerai'] as $s): ?><option <?=$s===$p['marital_status']?'selected':''?>><?=$s?></option><?php endforeach; ?></select></div><div><label>Kontak Darurat</label><input name="emergency_contact" value="<?=e($p['emergency_contact'])?>"></div><div class="full"><label>Alamat Domisili</label><textarea name="address"><?=e($p['address'])?></textarea></div></div><div class="notice" style="margin-top:14px">Nomor rekam medis dan NIK dikunci pada transaksi ini untuk menjaga konsistensi identitas pasien.</div><div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="btn" name="save">Simpan Perubahan</button></div></form></div><?php endif; ?>
